#!/bin/bash
# Installe le proxy MMR Rocket League sur ce VPS.
# Ne touche PAS pumpbot-sim, /root/simbots, ni aucun fichier de clés.
set -euo pipefail

DEST=/root/rl-mmr
UNIT=/etc/systemd/system/rl-mmr.service
RAW_PY="https://raw.githubusercontent.com/ElAlonsoo/kimchi/main/mmr_fetch.py"
# repli si raw.githubusercontent est lent
RAW_PY_GH="https://github.com/ElAlonsoo/kimchi/raw/main/mmr_fetch.py"

if [[ "$(id -u)" -ne 0 ]]; then
  echo "À lancer en root (console Hetzner)."
  exit 1
fi

echo "=== Installation MMR Rocket League (KvaraBallonDor) ==="
echo "Dossier : $DEST  (aucun autre dossier ne sera modifié)"

mkdir -p "$DEST"
cd "$DEST"

download() {
  local url="$1" out="$2"
  if command -v wget >/dev/null 2>&1; then
    wget -q -O "$out" "$url" && [[ -s "$out" ]] && return 0
  fi
  if command -v curl >/dev/null 2>&1; then
    curl -fsSL -o "$out" "$url" && [[ -s "$out" ]] && return 0
  fi
  return 1
}

TMP="$DEST/mmr_fetch.py.new"
base64 -d > "$TMP" << 'B64'

B64
mv -f "$TMP" "$DEST/mmr_fetch.py"
chmod 755 "$DEST/mmr_fetch.py"

cat > "$UNIT" << 'EOF'
[Unit]
Description=Rocket League MMR proxy (KvaraBallonDor)
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
WorkingDirectory=/root/rl-mmr
ExecStart=/usr/bin/python3 /root/rl-mmr/mmr_fetch.py
Restart=always
RestartSec=5
# Isolé : ne lit aucun env de bot, ne touche pas /root/simbots

[Install]
WantedBy=multi-user.target
EOF

# Pare-feu : n'agit que si ufw est déjà actif
if command -v ufw >/dev/null 2>&1; then
  if ufw status 2>/dev/null | grep -qi "Status: active"; then
    ufw allow 8765/tcp comment 'rl-mmr' >/dev/null 2>&1 || true
    echo "Port 8765 ouvert dans ufw."
  fi
fi

systemctl daemon-reload
systemctl enable rl-mmr >/dev/null
systemctl restart rl-mmr

echo "Service rl-mmr démarré, attente 10 s…"
sleep 10

python3 - << 'PY'
import json, urllib.request, urllib.error, sys

url = "http://127.0.0.1:8765/mmr.json"
try:
    with urllib.request.urlopen(url, timeout=5) as r:
        data = json.loads(r.read().decode("utf-8", "replace"))
except Exception as e:
    print()
    print("Service lancé, mais pas encore de réponse locale :", e)
    print("Vérifie : systemctl status rl-mmr")
    print("URL : http://49.13.50.89:8765/mmr.json")
    sys.exit(0)

def line(pl, label):
    p = None
    for x in (data.get("playlists") or []):
        if x.get("id") == pl:
            p = x
            break
    if not p:
        return f"  {label} : —"
    rank = p.get("rank") or "—"
    div = p.get("division") or ""
    mmr = p.get("mmr")
    mmr_s = "—" if mmr is None else str(mmr)
    extra = f" · {div}" if div else ""
    return f"  {label} : {rank}{extra}  —  {mmr_s}"

print()
print("=== MMR  KvaraBallonDor  ===")
ok = bool(data.get("ok"))
if ok:
    print("Statut : OK")
    print(line("1v1", "1V1"))
    print(line("2v2", "2V2"))
    print(line("3v3", "3V3"))
else:
    print("BLOQUÉ par Tracker")
    if data.get("stale") and data.get("playlists"):
        print("(anciennes valeurs conservées)")
        print(line("1v1", "1V1"))
        print(line("2v2", "2V2"))
        print(line("3v3", "3V3"))
    err = data.get("error") or ""
    if err:
        print("Erreur :", err[:280])
    print("Le service tourne et réessaie toutes les 60 s.")

print()
print("URL : http://49.13.50.89:8765/mmr.json")
print("Page statut : http://49.13.50.89:8765/status")
PY
